import{_ as a,c as d,o as t,a9 as r}from"./chunks/framework.BXLNC15u.js";const p=JSON.parse('{"title":"Structure of a message","description":"Message internals for commands, subscriptions, events, and streams","frontmatter":{"title":"Structure of a message","description":"Message internals for commands, subscriptions, events, and streams","order":209910},"headers":[],"relativePath":"handbook/2_building_business-logic/advanced/structure_of_a_message.md","filePath":"handbook/2_building_business-logic/advanced/structure_of_a_message.md","lastUpdated":1772015246000}'),i={name:"handbook/2_building_business-logic/advanced/structure_of_a_message.md"};function s(o,e,c,n,l,m){return t(),d("div",null,[...e[0]||(e[0]=[r('<h1 id="structure-of-a-message" tabindex="-1">Structure of a message <a class="header-anchor" href="#structure-of-a-message" aria-label="Permalink to “Structure of a message”">​</a></h1><h2 id="core-identifiers" tabindex="-1">Core identifiers <a class="header-anchor" href="#core-identifiers" aria-label="Permalink to “Core identifiers”">​</a></h2><h3 id="traceid" tabindex="-1"><code>traceId</code> <a class="header-anchor" href="#traceid" aria-label="Permalink to “traceId”">​</a></h3><p>Trace identifier for one full distributed flow.</p><h3 id="correlationid" tabindex="-1"><code>correlationId</code> <a class="header-anchor" href="#correlationid" aria-label="Permalink to “correlationId”">​</a></h3><p>Correlation identifier for one request/response or one stream session.</p><h3 id="id" tabindex="-1"><code>id</code> <a class="header-anchor" href="#id" aria-label="Permalink to “id”">​</a></h3><p>Unique message id.</p><h3 id="instanceid" tabindex="-1"><code>instanceId</code> <a class="header-anchor" href="#instanceid" aria-label="Permalink to “instanceId”">​</a></h3><p>Unique event bridge instance id (sender side).</p><h3 id="principalid-and-tenantid" tabindex="-1"><code>principalId</code> and <code>tenantId</code> <a class="header-anchor" href="#principalid-and-tenantid" aria-label="Permalink to “principalId and tenantId”">​</a></h3><p>Optional security/tenant metadata propagated through the flow.</p><h2 id="shared-message-fields" tabindex="-1">Shared message fields <a class="header-anchor" href="#shared-message-fields" aria-label="Permalink to “Shared message fields”">​</a></h2><table tabindex="0"><thead><tr><th>field</th><th>required</th><th>meaning</th></tr></thead><tbody><tr><td><code>messageType</code></td><td>yes</td><td>command/response/custom/info/stream</td></tr><tr><td><code>id</code></td><td>yes</td><td>message id</td></tr><tr><td><code>timestamp</code></td><td>yes</td><td>unix time in ms</td></tr><tr><td><code>traceId</code></td><td>yes</td><td>distributed trace id</td></tr><tr><td><code>sender</code></td><td>yes</td><td>sender address (<code>serviceName</code>, <code>serviceVersion</code>, <code>serviceTarget</code>, <code>instanceId</code>)</td></tr><tr><td><code>receiver</code></td><td>depends</td><td>target address for directed messages</td></tr><tr><td><code>payload</code></td><td>depends</td><td>message body</td></tr><tr><td><code>otp</code></td><td>no</td><td>OpenTelemetry propagation payload</td></tr></tbody></table><h2 id="stream-message-model" tabindex="-1">Stream message model <a class="header-anchor" href="#stream-message-model" aria-label="Permalink to “Stream message model”">​</a></h2><p><code>messageType: &#39;stream&#39;</code> uses frame-oriented payloads:</p><ul><li><code>open</code>: open request with <code>payload</code> + <code>parameter</code></li><li><code>start</code>: producer accepted and stream started</li><li><code>chunk</code>: one incremental result item</li><li><code>complete</code>: terminal success (optional final payload)</li><li><code>error</code>: terminal failure</li><li><code>cancel</code>: terminal cancellation</li><li><code>heartbeat</code>: optional keepalive frame</li></ul><p>A stream session is keyed by <code>correlationId</code>.</p><h2 id="practical-debugging-tips" tabindex="-1">Practical debugging tips <a class="header-anchor" href="#practical-debugging-tips" aria-label="Permalink to “Practical debugging tips”">​</a></h2><ul><li>use <code>traceId</code> for end-to-end flow views</li><li>use <code>correlationId</code> for one command call or stream session</li><li>inspect sender/receiver address to verify routing correctness</li><li>verify <code>eventName</code> for subscription matching and event-driven fan-out</li></ul>',20)])])}const u=a(i,[["render",s]]);export{p as __pageData,u as default};
